import{_ as a,o as t,c as i,a5 as r}from"./chunks/framework.BPFk9-tb.js";const u=JSON.parse('{"title":"Hbase Index - 首页","description":"","frontmatter":{"date":"2018-12-05T12:20:00","title":"Hbase Index - 首页","categories":["hbase","hbase indexer"],"tags":["hbase","hbase indexer"]},"headers":[{"level":2,"title":"简介（Introduction）","slug":"简介-introduction","link":"#简介-introduction","children":[]},{"level":2,"title":"开始使用Hbase Indexer（Getting started with the HBase Indexer）","slug":"开始使用hbase-indexer-getting-started-with-the-hbase-indexer","link":"#开始使用hbase-indexer-getting-started-with-the-hbase-indexer","children":[]},{"level":2,"title":"工作原理（How it works）","slug":"工作原理-how-it-works","link":"#工作原理-how-it-works","children":[]},{"level":2,"title":"横向扩展（Horizontal scalability）","slug":"横向扩展-horizontal-scalability","link":"#横向扩展-horizontal-scalability","children":[]},{"level":2,"title":"自动的错误处理（Automatic failure handling）","slug":"自动的错误处理-automatic-failure-handling","link":"#自动的错误处理-automatic-failure-handling","children":[]}],"relativePath":"posts/bigdata/hbase-indexer/home.md","filePath":"posts/bigdata/hbase-indexer/home.md"}'),n={name:"posts/bigdata/hbase-indexer/home.md"};function o(s,e,l,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="简介-introduction" tabindex="-1">简介（Introduction） <a class="header-anchor" href="#简介-introduction" aria-label="Permalink to &quot;简介（Introduction）&quot;">​</a></h2><p>The HBase Indexer project provides indexing (via <a href="http://lucene.apache.org/solr/" target="_blank" rel="noreferrer">Solr</a>) for content stored in <a href="http://hbase.apache.org/" target="_blank" rel="noreferrer">HBase</a>. It provides a flexible and extensible way of defining indexing rules, and is designed to scale.</p><p>Hbase Indexer项目可以为存储在HBase中的内容提供<a href="http://lucene.apache.org/solr/" target="_blank" rel="noreferrer">Solr</a>索引。它提供灵活的可扩展的方式来定义索引规则，且为大规模而生。</p><p>Indexing is performed asynchronously, so it does not impact write throughput on HBase. SolrCloud is used for storing the actual index in order to ensure scalability of the indexing.</p><p>索引是异步的，所以不会影响Hbase的写入吞吐量。SolrCloud用于存储实际的索引，以确保索引的可伸缩性。</p><h2 id="开始使用hbase-indexer-getting-started-with-the-hbase-indexer" tabindex="-1">开始使用Hbase Indexer（Getting started with the HBase Indexer） <a class="header-anchor" href="#开始使用hbase-indexer-getting-started-with-the-hbase-indexer" aria-label="Permalink to &quot;开始使用Hbase Indexer（Getting started with the HBase Indexer）&quot;">​</a></h2><ol><li><p>Make sure you&#39;ve got the required software installed, as detailed on the <a href="https://github.com/NGDATA/hbase-indexer/wiki/Requirements" target="_blank" rel="noreferrer">Requirements</a> page.</p></li><li><p>Follow the Tutorial to get a feel for how to use the HBase Indexer.</p></li><li><p>Customize your indexing setup as needed using the other reference documentation provided here.</p></li><li><p>确认所有要求的软件已经安装，具体内容在[要求]页。</p></li><li><p>按照教程来体验下如何使用Hbase Indexer。</p></li><li><p>通过提供的文档来调整索引的配置。</p></li></ol><h2 id="工作原理-how-it-works" tabindex="-1">工作原理（How it works） <a class="header-anchor" href="#工作原理-how-it-works" aria-label="Permalink to &quot;工作原理（How it works）&quot;">​</a></h2><p>The HBase Indexer works by acting as an HBase replication sink. As updates are written to HBase region servers, they are &quot;replicated&quot; asynchronously to the HBase Indexer processes.</p><p>Hbase Indxer扮演了Hbase复制集的角色。当数据写入Hbase的分区时，数据被异步的“复制”给Hbase Indexer处理器。</p><p>The indexer analyzes incoming HBase mutation events, and where applicable it creates Solr documents and pushes them to SolrCloud servers.</p><p>Hbase Indexer分析从Hbase发送过来的变化事件，当合适的时候创建Solr文档并发送给SolrCloud服务器。</p><p>The indexed documents in Solr contain enough information to uniquely identify the HBase row that they are based on, allowing you to use Solr to search for content that is stored in HBase.</p><p>Solr文档维护了足够多的信息用于唯一标识一条Hbase记录，这样允许你可能通过Solr来检索Hbase内容。</p><p>HBase replication is based on reading the HBase log files, which are the precise source of truth of the what is stored in HBase: there are no missing or no extra events. In various cases, the log also contains all the information needed to index, so that no expensive random-read on HBase is necessary (see the <code>read-row</code>attribute in the <a href="https://github.com/NGDATA/hbase-indexer/wiki/Indexer-configuration" target="_blank" rel="noreferrer">Indexer Configuration</a>).</p><p>HBase复制集是通过读取Hbase的日志文件，这些日志文件是HBASE中存储内容的精确来源：没有遗漏也没有额外的事件。在大多数情况下，日志含了索引需要的全部信息，因此不需要对Hbase进行昂贵的随机读取。（在[Indexer配置]中可查看<code>read-row</code>属性）。</p><p>HBase replication delivers (small) batches of events. HBase-indexer exploits this by avoiding double-indexing of the same row if it would have been updated twice in a short time frame, and as well will batch/buffer the updates towards Solr, which gives important performance gains. The updates are applied to Solr before confirming the processing of the events to HBase, so that no event loss is possible.</p><p>Hbase复制集（小规模）批量分发事件。Hbase indexer利用这一特性用于避免在一个很小的时间窗口期一条记录被更新两次而引起重复索引，也通过批量/缓存的方式来更新Solr，这样可以获得更好的性能。所有的更新会在Hbase处理确认之前更新到Solr中，因此不会出现丢失数据的情况。</p><h2 id="横向扩展-horizontal-scalability" tabindex="-1">横向扩展（Horizontal scalability） <a class="header-anchor" href="#横向扩展-horizontal-scalability" aria-label="Permalink to &quot;横向扩展（Horizontal scalability）&quot;">​</a></h2><p>All information about indexers is stored in ZooKeeper. New indexer hosts can always be added to a cluster, in the same way that HBase regionservers can be added to to an HBase cluster.</p><p>所有的索引信息都是保存在ZooKeeper中的。新的Indexer主机可以被添加为一个集群中，就像Hbase的分区服务器被添加到Hbase集群一样。</p><p>All indexing work for a single configured indexer is shared over all machines in the cluster. In this way, adding additional indexer nodes allows horizontal scaling.</p><p>同一索引配置的所有索引工作被分配给集群中的所有机器。这样说来，添加额外的索引节点就可以横向扩展。</p><h2 id="自动的错误处理-automatic-failure-handling" tabindex="-1">自动的错误处理（Automatic failure handling） <a class="header-anchor" href="#自动的错误处理-automatic-failure-handling" aria-label="Permalink to &quot;自动的错误处理（Automatic failure handling）&quot;">​</a></h2><p>The HBase replication system upon which the HBase Indexer is based is designed to handle hardware failures. Because the HBase Indexer is based on this system, it also benefits from the same ability to handle failures.</p><p>Hbase复制集系统为硬件错误处理做了设计。Hbase Indexer其于此系统，因此也从中获得了错误处理的能力。</p><p>In general, indexing nodes going down or Solr nodes going down will not result in any lost data in the HBase Indexer.</p><p>通常情况，索引节点或者Solr宕机不会导致Hbase Indexer中的数据丢失。</p>',28)])])}const b=a(n,[["render",o]]);export{u as __pageData,b as default};
